(function (all) { var mine = all["pl"] = all["pl"] || {}; var add = {"manual.831d0f72d242":"Pierwsze kroki","manual.f2f53974b760":"Freally Capture to studio na komputer dla systemów Windows, macOS i Linux. Ten podręcznik opisuje wersję 1.2.1, bieżące wydanie.","manual.4b5f10daa08b":"Otwórz Freally Capture. Za pierwszym razem poprosi cię o zaakceptowanie umowy licencyjnej; potem kreator konfiguracji sprawdzi twoją kartę graficzną i procesor i zaproponuje koder, rozmiar płótna i bitrate, z uzasadnieniem każdego wyboru.","manual.fe88634050bf":"Studio otwiera się na podglądzie programu z dokami <strong>Sceny</strong>, <strong>Źródła</strong>, <strong>Mikser</strong> i <strong>Sterowanie</strong>. Nie ma konta ani logowania.","manual.4c937d2528ca":"W <strong>macOS</strong> zezwól na <strong>Nagrywanie ekranu</strong> — a także na dostęp do <strong>Kamery</strong> i <strong>Mikrofonu</strong>, jeśli z nich korzystasz — w Ustawieniach systemowych → Prywatność i ochrona, a potem ponownie otwórz aplikację. W <strong>Linux z Wayland</strong> to okno dialogowe samego pulpitu pyta, który ekran lub które okno udostępnić.","manual.adc8f305f8f8":"Dodaj pierwsze źródło (zobacz <a href=\"#build-a-scene\">Zbuduj scenę</a>) i możesz już nagrywać lub wyjść na żywo.","manual.46e49bd74b1d":"Zbuduj scenę","manual.f779d891c1f2":"Scena to stos źródeł składanych na karcie graficznej. Jedno źródło może być współdzielone przez kilka scen.","manual.5a1c5f778fdb":"W doku <strong>Źródła</strong> kliknij <strong>Dodaj źródło</strong> i wybierz typ: <strong>Ekran</strong>, <strong>Okno</strong>, <strong>Gra</strong>, <strong>Kamera internetowa / karta przechwytująca</strong>, <strong>Przeglądarka</strong>, <strong>Media</strong>, <strong>Obraz</strong>, <strong>Tekst</strong>, <strong>Kolor</strong> lub <strong>Dźwięk</strong>.","manual.2a2d9e2015b5":"Dodaj <strong>Przechwytywanie ekranu</strong>: podgląd programu wypełni się twoim ekranem.","manual.80c8e9c8176f":"Dodaj źródło <strong>Kamera internetowa</strong>, przeciągnij je do rogu płótna i zmień jego rozmiar uchwytami.","manual.264150f36676":"Dodaj na wierzch nakładkę <strong>Obraz</strong> lub <strong>Przeglądarka</strong>. Kolejność na liście to kolejność na płótnie: góra listy to przód.","manual.a329c46899d6":"Utwórz więcej scen w doku <strong>Sceny</strong> — na przykład „Wkrótce zaczynamy”, „Rozgrywka” i „Zaraz wracam” — i przełączaj się między nimi.","manual.9c8d5730d1bb":"<strong>Wskazówka:</strong> Zmień właściwości współdzielonego źródła raz, a zmienią się w każdej scenie, która go używa.","manual.fd869e76d280":"<strong>Podgląd:</strong> w Windows, macOS i Linux z X11 podgląd programu jest malowany prosto z karty graficznej, więc przeciąganie, skalowanie i obracanie działają natychmiast. W Wayland używany jest standardowy podgląd, z tą samą edycją na płótnie.","manual.87eca68fecaa":"Filtry i przejścia","manual.36a962cf3902":"Nakładaj filtry na każde źródło, na karcie graficznej, i wybieraj, jak jedna scena ustępuje miejsca następnej.","manual.4708b4dbab34":"Dodaj chroma key","manual.9df34cebcaf5":"Kliknij prawym przyciskiem źródło — na przykład kamerę na tle green screen — i wybierz <strong>Filtry</strong>.","manual.9981601a6174":"Dodaj <strong>Chroma Key</strong> i dostosuj parametry <strong>Kolor kluczowy</strong>, <strong>Podobieństwo</strong>, <strong>Gładkość</strong> i <strong>Poświata</strong>: kluczowany kolor znika na żywo na płótnie.","manual.b76bd309a9f6":"Dodawaj kolejne filtry w miarę potrzeb — <strong>Korekcja koloru</strong>, <strong>LUT</strong>, <strong>Rozmycie</strong>, <strong>Maska</strong>, <strong>Wyostrzanie</strong> — i przeciągaj je, by zmienić kolejność w łańcuchu.","manual.db41fe5a40e4":"Ustaw przejście","manual.bea9e11be98d":"W doku <strong>Sterowanie</strong> otwórz wybór przejścia, wybierz <strong>Cięcie</strong>, <strong>Przenikanie</strong>, <strong>Przesunięcie</strong>, <strong>Przeciągnięcie</strong>, <strong>Stinger</strong> lub <strong>Przejście luma</strong> i ustaw czas trwania.","manual.eada58ce5b2e":"W przypadku <strong>Stingera</strong> wybierz plik multimedialny i jego punkt przejścia; w przypadku <strong>Przejścia luma</strong> wybierz gradient i jego miękkość.","manual.79756cb8b209":"Przełącz scenę, by zobaczyć przejście. W trybie studia odtwarza się ono, gdy wysyłasz podgląd do programu.","manual.2c0c025b4264":"Kompozytor i efekty wizualne","manual.b768e85eff32":"Pochylenie 3D, klucze wyjściowe, stopklatka i klonowanie, rodzina rozmyć, przejścia ruchu z regułami, studio shaderów, maski Béziera i stingery z matte ścieżki.","manual.d2b720eca5a5":"Pochylenie 3D i perspektywa","manual.d665cc2f2296":"Otwórz <strong>Edytuj transformację…</strong> na elemencie i ustaw <strong>Pochylenie X</strong>, <strong>Pochylenie Y</strong> oraz siłę <strong>Perspektywy</strong>, by osadzić źródło w 3D. Transformacja bez pochylenia renderuje się dokładnie tak jak wcześniej.","manual.c4077ba2b72d":"Klucze wyjściowe","manual.d4220af54ed9":"Otwórz <strong>Narzędzia → Klucze wyjściowe</strong> i dodaj dowolne źródło jako warstwę nad <strong>wyjściem programu</strong>, ponad każdą sceną i przez każdą zmianę sceny — logo stacji, plakietkę NA ŻYWO, belkę z podpisem.","manual.0677e571c1f8":"Zmieniaj kolejność warstw i ustawiaj dla każdej krycie, pozycję, rozmiar oraz włączenie lub wyłączenie. Pojawiają się tak samo w podglądzie, nagraniu, streamie i widoku wielokamerowym.","manual.1e484119e149":"Stopklatka i klonowanie źródeł","manual.4cdb8e22f58b":"Kliknij prawym przyciskiem źródło, otwórz <strong>Filtry</strong> i dodaj <strong>Zamroź</strong>: zatrzymuje ostatnią klatkę jednocześnie w programie, podglądzie, nagraniu i streamie. Wyłącz go, by odmrozić obraz.","manual.59fd957b48dc":"Kliknij przycisk <strong>Klonuj</strong> (⧉) w wierszu źródła, by umieścić jeden sygnał w kilku scenach lub miejscach, a każdy klon ma własną transformację i filtry.","manual.a90410d6b30c":"Rozmycia","manual.eeb69e428aa3":"W <strong>Filtrach</strong> źródła dodaj jedno z rozmyć obok gaussowskiego: <strong>kierunkowe</strong> (smuga ruchu pod kątem), <strong>promieniste</strong> (wirowanie wokół środka), <strong>Zoom</strong> (smuga efektu dolly zoom) lub <strong>Pikselizacja</strong> (mozaika).","manual.54261c9f6b8f":"Przejście ruchu i reguły przejść","manual.ef17a04962be":"Wybierz przejście <strong>Ruch</strong>: elementy obecne w obu scenach płynnie przechodzą od dawnej pozycji, skali, obrotu i kadrowania do nowych zamiast cięcia, a elementy obecne tylko w jednej scenie pojawiają się lub znikają przez przenikanie.","manual.e31792f9e737":"Otwórz <strong>Narzędzia → Reguły przejść</strong>, by nadać jednej parze scen własne przejście i czas trwania. Dla własnego wejścia elementu ustaw pojawianie się <strong>Odsłonięcie</strong> w <strong>Edytuj transformację…</strong>.","manual.bb4e30a1ea68":"Studio shaderów WGSL","manual.e475acf03bea":"Dodaj <strong>efekt WGSL użytkownika</strong> jako filtr i edytuj go na żywo. Jego suwaki powstają z adnotacji <code>// @param</code>, a wbudowana galeria zawiera skalę szarości, odwrócenie, linie skanowania i winietę.","manual.424ca3316822":"<strong>Wskazówka:</strong> Shader jest kompilowany i sprawdzany w trakcie pisania. Nieprawidłowy shader jest ignorowany, a źródło renderuje się bez filtra — nigdy nie dochodzi do awarii.","manual.c24e8b5ee2c0":"Maski Béziera","manual.37870edaacbc":"Dodaj filtr <strong>maska odręczna</strong> i narysuj zamkniętą ścieżkę: przeciągaj uchwyty, kliknij dwukrotnie, by dodać punkt, kliknij prawym przyciskiem, by go usunąć. Filtr ma gotowe kształty, wtapianie dla każdej krawędzi i odwrócenie.","manual.f44ad1306530":"Wyeksportuj dowolną ścieżkę jako wzór <strong>przejścia luma</strong> w skali szarości, by użyć kształtu ponownie jako przejścia.","manual.e4c8b0c52b3e":"Stingery z matte ścieżki","manual.b35494db6ce6":"Ustaw stinger tak, by przenosił przezroczystość jako <strong>Matte ścieżki</strong>, z wypełnieniem i matte <strong>Obok siebie</strong> lub <strong>Jeden na drugim</strong>, aby przezroczystość przetrwała kodeki, które ją odrzucają (H.264 i HEVC). Opcjonalnie <strong>przyciszaj dźwięk programu</strong> pod własnym dźwiękiem stingera, gdy ten gra.","manual.3879f0c73d18":"Nakładki i więcej źródeł","manual.cea21c089e39":"Powtórki, playlisty, tytuły, mierniki, nakładka statystyk, minutniki, nakładka wejść i dwa sygnały sieciowe — wszystko z menu <strong>+ / Dodaj źródło</strong> w doku <strong>Źródła</strong>.","manual.4a459b922e4b":"Natychmiastowa powtórka","manual.2e042aa67065":"Najpierw uzbrój bufor powtórek (<strong>Uzbrój powtórkę</strong> w doku <strong>Sterowanie</strong>), potem wybierz <strong>Natychmiastowa powtórka</strong> z <strong>+ / Dodaj źródło</strong> i umieść ją w scenie.","manual.d7645da473a6":"Wpuść ostatnie sekundy do programu skrótem powtórki — skopiowane bez ponownego kodowania i odtwarzane z prędkością <strong>100%</strong>, <strong>50%</strong> lub <strong>25%</strong>, spowolnione, a nie uzupełnione wymyślonymi klatkami. Podczas odtwarzania możesz przewijać lub wstrzymać.","manual.5b8095e70de0":"Na końcu źródło samo się czyści, więc program sam wraca do obrazu na żywo.","manual.6433eaab9b10":"<strong>Wskazówka:</strong> Powtórka w zwolnionym tempie jest celowo bezgłośna: spowolniony dźwięk byłby rozmazany, więc zostaje pominięty, a nie podrabiany.","manual.f0b63d46cd74":"Playlista mediów i muzyka w tle","manual.37ed12f9d130":"Dodaj <strong>Playlista mediów (bez przerw)</strong> i zbuduj uporządkowaną listę z punktami wejścia i wyjścia oraz punktami sygnałowymi dla każdej pozycji. Cała lista jest odtwarzana przez jeden dekoder, więc połączenia są dokładne co do klatki i naprawdę bez przerw.","manual.ef41fa6ad9b5":"Wybierz sposób odtwarzania — <strong>Pętla</strong>, <strong>Losowo</strong> lub <strong>Zatrzymaj na ostatnim</strong> — i przechodź przez listę skrótami do następnej i poprzedniej pozycji. Playlista tylko z dźwiękiem pokazuje na płótnie <strong>nazwę bieżącego utworu</strong> i gra przez własny kanał miksera; kliknij przycisk <strong>Monitor</strong> tego kanału, by ją usłyszeć.","manual.6e641ae2bd92":"Do muzyki, która gra bez niczego na ekranie, wybierz zamiast tego <strong>+ / Dodaj źródło → Muzyka w tle…</strong> i wskaż jeden lub więcej plików <code>.mp3</code>, <code>.wav</code> lub <code>.flac</code>, w razie potrzeby w losowej kolejności. Wycisza ono własny dźwięk wideo w tle, więc zawsze słychać tylko jedną rzecz.","manual.b9aad55133bf":"Projektant tytułów i tablic wyników","manual.5382c093aaef":"Dodaj <strong>Tytuł / Tablica wyników</strong>, by otworzyć projektanta: układaj warstwy <strong>Tekst</strong>, <strong>Obraz</strong> i <strong>Kształt</strong>, z tekstem z obrysem i cieniem oraz animacjami wejścia i wyjścia (przenikanie, przesunięcie, wymazanie).","manual.7b8fea70655a":"Powiąż pola z obserwowanym plikiem (komórką CSV lub wskaźnikiem JSON) albo ze zmienną studia, a potem steruj nimi na żywo: zmień nazwisko, edytuj wynik lub odtwórz animację bez ruszania sceny.","manual.88a9422e37a9":"Wizualizer dźwięku","manual.87f4a5bdd624":"Dodaj <strong>Wizualizer dźwięku</strong> i wybierz styl — <strong>Słupki widma</strong>, <strong>Oscyloskop</strong> lub stereofoniczne <strong>Mierniki VU</strong> — a potem powiąż go z dowolnym kanałem miksera, ścieżką lub miksem master. Pokazuje też dźwięk wideo w tle.","manual.0ae90a461adb":"We <strong>Właściwościach</strong> źródła włącz <strong>Klasyczne kolory</strong>, by uzyskać pasma zielone, żółte i czerwone, albo zostaw tę opcję wyłączoną, by mieć jeden jednolity kolor. Są tam też rozmiar, liczba słupków i szybkość opadania.","manual.0d1ceffb08ba":"<strong>Wskazówka:</strong> Wizualizer słucha <strong>za faderem</strong>, więc wyciszone źródło pokazuje płaską linię: widzisz dokładnie to, co słyszysz.","manual.ec642e1cf0cc":"Nakładka statystyk, timer splitów i nakładka wejść","manual.6b4fe6f81cb0":"Dodaj <strong>Statystyki wydajności (HUD)</strong>, by pokazać na płótnie liczby zmierzone przez dok statystyk — klatki na sekundę, CPU, pamięć, czas składania na GPU, utracone klatki i bitrate na żywo — a każdy wiersz można włączyć lub wyłączyć. Wykorzystanie GPU jest celowo pominięte, bo nie jest mierzone.","manual.cbd8a4b88736":"Dodaj <strong>Timer splitów (speedrun)</strong>, zaimportuj plik LiveSplit <code>.lss</code> i prowadź przebieg globalnymi skrótami split, cofnij, pomiń i resetuj, porównując go z rekordem osobistym, najlepszymi segmentami lub średnią. Plik jest tylko odczytywany; przebieg nigdy nie jest do niego zapisywany.","manual.fbf4bbeaf903":"Dodaj <strong>Nakładka wejść (klawisze/pad)</strong>, by pokazywać na żywo klawiaturę, mysz i gamepad w jednym z czterech układów (WASD, kompaktowa klawiatura, pad z dwiema gałkami, 8-kierunkowy fight stick). Klawiatura i mysz działają w Windows; gamepady działają we wszystkich trzech systemach.","manual.bf794edb3c25":"Pasek mediów społecznościowych i kanałów","manual.5f898056ef11":"Dodaj <strong>Pasek społecznościowy</strong> z <strong>+ / Dodaj źródło</strong>: panel z listą twoich nazw użytkownika. Wybierz platformę dla każdego wiersza — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> jako kolorowe plakietki albo <strong>Własny</strong> z własną etykietą i kolorem — i wpisz nazwę (na przykład <code>@mychannel</code>). Dodaj opcjonalny wiersz nagłówka („Obserwuj mnie”), zmień kolejność wierszy i ustaw rozmiar tekstu oraz kolory.","manual.1dab9389547a":"Każde pole pozostaje edytowalne we <strong>Właściwościach</strong> źródła. Wiersze bez nazwy są pomijane, więc możesz trzymać pełną listę i wypełniać tylko to, czego używasz.","manual.1a4ac3c2e0bf":"Wyróżniona wiadomość czatu","manual.c5d58a7d58be":"Otwórz <strong>Narzędzia → Wyróżniona wiadomość czatu…</strong> (albo paletę poleceń). Okno pokazuje najnowsze wiersze z każdej działającej nakładki czatu: kliknij <strong>Wyróżnij</strong> przy jednym z nich, by przypiąć go do programu jako baner, który widzą widzowie streamu i nagrania.","manual.162d364796a2":"Ustaw w oknie kolory <strong>banera</strong> i <strong>tekstu</strong> i kliknij <strong>Wyczyść</strong>, by zdjąć baner z anteny. Samo przypięcie celowo znika po restarcie: wczorajsze pozdrowienie nigdy nie wraca w dzisiejszym programie.","manual.89a84c53e014":"Podświetlenie kursora i efekty kliknięć","manual.d0a5d9fb047d":"Kliknij prawym przyciskiem przechwytywanie ekranu lub okna, otwórz <strong>Filtry</strong> i dodaj <strong>Efekty kursora</strong>: <strong>Poświata kursora</strong> (kolor i promień), oznaczone kolorami <strong>Fale kliknięć</strong> lewym i prawym przyciskiem oraz opcjonalny <strong>Podgląd klawiszy</strong> obok wskaźnika. Zmiany widać na żywo.","manual.4a17c44757e4":"<strong>Uwaga:</strong> Efekty kursora działają tylko w Windows; macOS i Linux same rysują kursor. Nakładka wejść i podgląd klawiszy odczytują wejście <strong>tylko wtedy, gdy są włączone</strong>, i rysują je prosto w obrazie: nic nie jest przechowywane ani rejestrowane.","manual.8bdb1aadf964":"Źródła sieciowe: odbiór w sieci LAN i Freally Link","manual.797fe86a1fe8":"Dodaj <strong>Odbiór LAN (nasłuch SRT/RTMP)</strong>, by otworzyć nasłuch na tym komputerze, a potem skieruj aplikację kamery w telefonie, koder lub drugi komputer na pokazany adres (z kodem QR). Sygnał trafia do sceny z własnym kanałem miksera. SRT może używać opcjonalnego hasła AES; RTMP nie ma własnego uwierzytelniania, więc formularz preferuje SRT.","manual.e2761818ccef":"Aby udostępniać obraz między dwiema kopiami Freally Capture, włącz wyjście <strong>Freally Link</strong> na komputerze <strong>wysyłającym</strong> i ustaw jego <strong>Klucz parowania</strong> — bez niego wyjścia nie da się włączyć. Na komputerze <strong>odbierającym</strong> dodaj <strong>Freally Link (inna instancja)</strong>, kliknij <strong>Skanuj sieć LAN</strong> i wpisz klucz: program nadawcy pojawi się jako źródło. Żadna ze stron nie potrzebuje ffmpeg, a odbiorca bez klucza nigdy nie zobaczy ani jednej klatki.","manual.a793cb271e32":"<strong>Uwaga:</strong> Oba źródła sieciowe są <strong>wyłączone, dopóki ich nie dodasz</strong>, pozostają w twojej własnej sieci i nigdy nie dotykają internetu: nic cię nie znajdzie i nic nie łączy się na zewnątrz.","manual.de10be5dcf2c":"Odliczanie „Wkrótce zaczynamy”","manual.71b47ef78ea4":"Ekran oczekiwania przed programem jednym kliknięciem: duże odliczanie do startu na tle obrazu, GIF-a, wideo, gradientu lub z muzyką, które miga przy zerze i czeka, aż przełączysz na program.","manual.303493002776":"Dodaj odliczanie","manual.f78f2994b5d5":"W doku <strong>Źródła</strong> otwórz <strong>+ / Dodaj źródło</strong> i wybierz <strong>Wkrótce zaczynamy…</strong>. W scenie pojawi się odliczanie na całe płótno — podpis nad dużą liczbą.","manual.c4bff5a4f06e":"Wpisz <strong>podpis</strong> („Wkrótce zaczynamy”, „Zaraz wracam”), a potem ustaw czas <strong>wyborem godziny</strong>: <strong>godzina</strong> (1–12), <strong>minuta</strong> w krokach co pięć minut oraz <strong>AM</strong> lub <strong>PM</strong>. Źródło odlicza do tej pory dnia.","manual.59b00df516f1":"Przy zerze odliczanie <strong>miga i zatrzymuje się na 0:00:00</strong> — nigdy samo nie przełącza scen. Przełącz na scenę na żywo, gdy będziesz gotowy. Każde pole pozostaje edytowalne we <strong>Właściwościach</strong> źródła.","manual.1dfb2d817d39":"Wybierz tło","manual.edc2450aeecd":"Wybierz wypełnienie: dwukolorowy <strong>Gradient</strong> (domyślnie), <strong>Jednolity</strong> kolor, <strong>Obraz</strong> (kliknij <strong>Przeglądaj…</strong>) albo <strong>Przezroczysty</strong>, by prześwitywało źródło znajdujące się pod spodem.","manual.07a5fd9ac032":"Wybierz plik <strong>GIF</strong> lub <strong>wideo</strong>, a będzie odtwarzany w pętli za cyframi, <strong>przeskalowany do dopasowania i wyśrodkowany</strong>, więc widać cały obraz i nic nie jest przycięte.","manual.1cda5be75376":"Dodaj <strong>muzykę w tle</strong> przyciskiem <strong>Przeglądaj…</strong> w oknie dialogowym (MP3, WAV, FLAC, M4A, AAC, OGG lub Opus). Gra w pętli, słyszysz ją w podglądzie i jest częścią nagrania oraz streamu. Własny dźwięk wideo w tle jest wyciszany, więc zawsze słychać tylko jedną rzecz.","manual.b39b6b7add20":"<strong>Wskazówka:</strong> Jeśli chcesz muzyki za zwykłym ekranem, zostaw tło na Gradient lub Przezroczysty i dodaj muzykę: czyste odliczanie ze ścieżką dźwiękową.","manual.84f506f4fca5":"Mikser dźwięku","manual.480e299c8728":"Miksuj każde źródło dźwięku, wysyłaj je na maksymalnie 6 ścieżek i oczyszczaj dźwięk mikrofonu — wszystko na żywo.","manual.bcbc220b3e63":"Każde źródło dźwięku to kanał w <strong>Mikserze</strong>: nazwa, miernik poziomu, fader, wyciszenie, odsłuch, filtry i kropki ścieżek (1–6).","manual.03b920dc5376":"Przeciągnij fader, by ustawić poziom, kliknij <strong>Wycisz</strong> lub <strong>Monitor</strong> i wyślij źródło na dowolną z 6 ścieżek.","manual.9a9991c7dc36":"Otwórz <strong>filtry</strong> źródła i dodaj <strong>Redukcja szumów</strong> (klasyczne przetwarzanie sygnału, bez AI), <strong>Bramka szumów</strong>, <strong>Kompresor</strong>, <strong>Limiter</strong>, <strong>Korektor</strong> lub <strong>Wzmocnienie</strong>.","manual.1a58b91bc5aa":"Przypisz skrót <strong>push-to-talk</strong> lub <strong>push-to-mute</strong> i obserwuj miernik <strong>LUFS</strong>, by śledzić głośność programu.","manual.7158a36ed4d5":"<strong>Uwaga dotycząca macOS:</strong> macOS sam z siebie nie udostępnia aplikacjom tego, „co słyszysz”. Użyj dźwięku ScreenCaptureKit (macOS 13 lub nowszy), gdzie jest dostępny, albo zainstaluj urządzenie wirtualne, takie jak BlackHole, i wybierz je jako źródło dźwięku systemowego. Freally Capture cię poprowadzi i nagrywa dalej, nawet jeśli jednego ze źródeł nie da się otworzyć.","manual.bfdd510698ef":"Nagrywaj","manual.e39b756fce99":"Nagrywaj program na kilku ścieżkach sprzętowym koderem karty graficznej albo bezstratnie we własnym formacie Capture.","manual.ad438c2dbf4b":"W <strong>Ustawienia → Wyjście</strong> wybierz koder. Freally Capture znajduje <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> lub <strong>VideoToolbox</strong> i wybiera najlepszy; <strong>x264</strong> na procesorze jest zawsze dostępny jako zapas.","manual.3bc1870f8449":"Wybierz kontener — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> lub <strong>WebM</strong> — albo własny bezstratny format Capture <strong>freally-video</strong> (<code>.frec</code>), który nie wymaga instalowania niczego więcej.","manual.e2a332927058":"Wysyłaj źródła na ścieżki audio (maksymalnie 6), aby mikrofon, dźwięk systemowy i goście pozostali rozdzieleni do montażu. Opcjonalnie włącz <strong>dzielenie plików</strong> i <strong>kopię lokalną z osobnymi ścieżkami podczas streamingu</strong>.","manual.e0fa2f5a9430":"Kliknij <strong>Rozpocznij nagrywanie</strong> w doku <strong>Sterowanie</strong>. Zielona kropka <strong>REC</strong> pokazuje czas i liczbę ścieżek. Kliknij <strong>Zatrzymaj</strong>, by zakończyć plik.","manual.b1eb969490f1":"<strong>Uwaga o kodekach:</strong> MP4 z H.264 i AAC (oraz HEVC lub AV1) używa kodeków objętych patentami, dostarczanych przez <strong>ffmpeg</strong>, który <em>nie jest dołączony</em>: Freally Capture pobiera go, gdy pierwszy raz go potrzebujesz, i sprawdza. Bezstratny format <strong>freally-video</strong> nie wymaga pobierania niczego.","manual.691bff5377a8":"Nagrywanie i powtórki w głąb","manual.3c2d08430816":"Wszystko wokół pliku: osobne nagrania każdego źródła, przycinarka klipów, prawdziwa przezroczystość, dzielenie i znaczniki przy zdarzeniach, zadania po nagraniu, kontrola integralności i kod czasowy SMPTE. Wszystko to jest wyłączone, dopóki tego nie włączysz, i nic z tego nie łączy się z internetem.","manual.537ffa2b9063":"Nagrywanie ISO dla każdego źródła","manual.e57aa725fa41":"Otwórz <strong>Ustawienia → Wyjście</strong> i znajdź <strong>Nagrywanie ISO</strong>. Włącz <strong>Nagrywaj „{name}” jako osobny plik ISO</strong> dla każdego źródła, które chcesz mieć czyste: każde jest nagrywane przed składaniem, w rozmiarze płótna i z jego liczbą klatek na sekundę, więc każdy plik pokrywa się z programem na osi czasu montażu. Każdy gość zdalny jest źródłem, więc każdy gość też dostaje swój plik.","manual.4bce8f25ec9c":"Zostaw zaznaczone <strong>Nagrywaj z filtrami źródła</strong>, by uzyskać przetworzony obraz, albo odznacz, by nagrać surowe źródło, i wybierz dla każdego nagrania <strong>Format ISO</strong> i <strong>Enkoder wideo ISO</strong>. Dźwięk jest pobierany za filtrami, ale przed faderem i wyciszeniem, więc decyzja podjęta przy miksowaniu nigdy nie wycisza pliku ISO.","manual.7f29ae4e2c55":"<strong>Wskazówka:</strong> Dwa nagrania ISO to komfortowe obciążenie dla karty graficznej ze średniej półki; każde kolejne kosztuje dodatkowe renderowanie i kodowanie, i panel o tym mówi.","manual.b2aad668b8b9":"Przycinarka powtórek i klipów","manual.c8af16e1cd4f":"Otwórz zapisane nagranie w oknie <strong>Przytnij</strong> z listy nagrań, przechodź po nim przyciskami <strong>Klatka wstecz</strong> i <strong>Klatka naprzód</strong> i ustawiaj punkty przyciskami <strong>Punkt wejścia</strong> i <strong>Punkt wyjścia</strong>, oglądając materiał.","manual.1f80dfd03a36":"Przed eksportem sprawdź plakietkę. Zielona <em>„Eksport bez ponownego kodowania”</em> oznacza, że punkt wejścia leży na klatce kluczowej (niemal natychmiast i bezstratnie); bursztynowa plakietka ostrzega, że nastąpi ponowne kodowanie — naciśnij <strong>Klatka kluczowa</strong>, by przyciągnąć punkt wejścia i uzyskać bezstratne cięcie. Kliknij <strong>Eksportuj klip</strong> lub <strong>9:16</strong>, by wyeksportować wersję pionową.","manual.8a92b0b480f4":"Nagrywanie z przezroczystością","manual.79bfd450e6aa":"W <strong>Ustawienia → Wyjście</strong> włącz <strong>Nagrywaj z przezroczystością (alfa)</strong>, by nagrywać program na przezroczystym tle do formatu <code>.frec</code> Capture. Nagranie dostaje własne przezroczyste renderowanie, więc podgląd i stream zachowują normalny obraz. Z listy nagrań wyeksportuj plik <code>.mov</code> <strong>ProRes 4444</strong> lub <strong>QuickTime Animation (QTRLE)</strong> dla swojego programu do montażu; MP4 i MKV spłaszczają przezroczystość.","manual.fade0a9d0454":"<strong>Uwaga:</strong> Przezroczystość to tylko flaga w nagłówku <code>.frec</code>, więc te pliki odtwarzają się wszędzie tam, gdzie <code>.frec</code>, a starsze pliki otwierają się jako nieprzezroczyste.","manual.33e5c9a96c5d":"Dzielenie i automatyczne znaczniki","manual.5596d47693a3":"W ustawieniach dzielenia dla <code>.frec</code> wybierz rozpoczynanie nowego pliku przy <strong>zmianie sceny</strong>, <strong>znaczniku</strong> lub <strong>kroku scenariusza</strong>. Każda część zaczyna się dokładnie na klatce tego zdarzenia, a część trwa co najmniej sekundę, więc seria zdarzeń nie może utworzyć stosu malutkich plików.","manual.7fc20a49c196":"Włącz <strong>Automatycznie wstawiaj znaczniki rozdziałów przy zdarzeniach studia</strong>, by oznaczać jako rozdziały zmiany scen, zapisane powtórki, ponowne połączenia, serie utraconych klatek, alarmy i akcje reguł. Trafiają one do tytułów rozdziałów MKV i do pliku <code>.chapters.txt</code> obok nagrania, razem ze znacznikami, które wstawiasz skrótem.","manual.519fceb746f3":"Po nagraniu: potok i kontrola integralności","manual.561bb55d7a18":"Zbuduj <strong>Potok po nagraniu</strong> dla każdego profilu ze stałego zestawu kroków — <strong>Zweryfikuj</strong>, <strong>Remuksuj do MP4</strong>, <strong>Znormalizuj głośność</strong>, <strong>Zmień nazwę</strong>, <strong>Przenieś do folderu</strong>, <strong>Skopiuj do folderu</strong>, <strong>Pokaż w menedżerze plików</strong> i <strong>Powiadom skrypty Lua</strong>. Działa w tle z kolejką na żywo i zatrzymuje się przy pierwszym niepowodzeniu. Celowo nie ma kroku „uruchom dowolne polecenie”.","manual.2f93cddd1f21":"Uruchom kontrolę integralności po nagraniu lub kiedy chcesz, by dostać prosty wynik OK, ostrzeżenie lub błąd dla pozycji <strong>Kontener</strong>, <strong>Ciągłość wideo</strong>, <strong>Ciągłość audio</strong>, <strong>Przeplot audio i wideo</strong> i <strong>Czas trwania</strong>. Pliki <code>.frec</code> są sprawdzane dogłębnie; inne pliki przechodzą kontrolę struktury i dekodowania przez ffmpeg.","manual.0d291aee5546":"Eksportuj kopię do udostępnienia po zatrzymaniu","manual.124d2a00ed27":"W <strong>Ustawienia → Wyjście</strong>, z kontenerem ustawionym na <code>.frec</code>, zaznacz <strong>Zapisz też udostępnialny plik MP4 obok mastera</strong>. Po zakończeniu nagrania eksport w tle zapisuje obok bezstratnego mastera plik <code>.mp4</code>, który każdy może odtworzyć.","manual.a37303723389":"Kopia pojawia się w kolejce po nagraniu, ma nazwę, która nigdy niczego nie nadpisuje, i nigdy nie dotyka mastera. Jest wyłączona, dopóki jej nie włączysz.","manual.7ed8656eb1ff":"Kod czasowy SMPTE LTC","manual.3d97874c3064":"Otwórz <strong>Timecode SMPTE (LTC)</strong>, włącz <strong>Generuj LTC na ścieżce</strong> i wybierz ścieżkę miksera oraz liczbę klatek na sekundę, by zasilać zewnętrzne rejestratory i kamery. Ustaw <strong>Odczytuj LTC z</strong> na wejście audio, by pokazywać wiersz kodu czasowego w nakładce statystyk i wstawiać znaczniki rozdziałów LTC. Klasyczny dźwiękowy kod czasowy, całkowicie offline, z dokładnością do jednej klatki przy 24, 25 i 30 fps.","manual.a9f690169703":"Wyjdź na żywo","manual.8f6df4580812":"Streamuj prosto ze swojego komputera na platformę przez RTMP lub RTMPS — nigdy przez nasz serwer.","manual.dba22b61cdcc":"Otwórz <strong>Ustawienia → Stream</strong> i kliknij <strong>Dodaj cel</strong>. Wybierz <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> lub <strong>Własny RTMP</strong>.","manual.2192731aac47":"Wklej swój <strong>klucz streamu</strong> — przechowywany na twoim komputerze i wyświetlany w zamaskowanej formie — i ustaw bitrate oraz koder dla tej usługi.","manual.040014e94f16":"Kliknij <strong>Rozpocznij transmisję</strong> w doku <strong>Sterowanie</strong>. Zapala się kontrolka <strong>Na żywo</strong>, a dok statystyk pokazuje bitrate, utracone klatki i stan streamu.","manual.0cd441959cb4":"Jeśli połączenie zostanie zerwane, Freally Capture <strong>sam połączy się ponownie</strong>, a lokalne nagranie trwa niezależnie od tego, co dzieje się ze streamem. Ustaw <strong>opóźnienie streamu</strong>, jeśli go potrzebujesz.","manual.dc8ebcea4893":"Kliknij <strong>Zakończ transmisję</strong>, by zatrzymać stream.","manual.973adc03e43c":"Bezpieczeństwo emisji","manual.53fa9293a65e":"Jak nie stracić programu — przed, w trakcie i po.","manual.de8792b14216":"Przed: lista kontrolna przed wejściem na żywo","manual.ed9a4b7bfaf5":"Kliknięcie <strong>Rozpocznij transmisję</strong> najpierw uruchamia listę kontrolną: cele streamu mają klucze, znaleziono działający koder, każde źródło jest sprawne i jest dość miejsca na dysku na nagranie — każdy punkt na zielono lub czerwono, z poprawką jednym kliknięciem — plus przypomnienia o poziomach mikrofonu i dźwięku pulpitu oraz o buforze powtórek, które nigdy nie blokują programu z samym ekranem. Ustawienie może <strong>wstrzymać Rozpocznij transmisję, dopóki każde blokujące sprawdzenie nie będzie zielone</strong>; w przeciwnym razie dostępne jest „Rozpocznij transmisję mimo to”.","manual.9b63c5c64ba1":"W trakcie: alarmy, stan źródeł i przełączanie awaryjne","manual.9c386b745073":"<strong>Alarmy bezpieczeństwa</strong> czuwają, gdy jesteś na żywo lub nagrywasz: cichy dźwięk programu, długotrwałe przesterowanie, czarny lub zamrożony obraz oraz <em>prognoza</em> kończącego się miejsca na dysku („około 22 minut przy obecnym bitrate”). Pojawiają się jako baner, który możesz zamknąć, a czytniki ekranu je ogłaszają — nigdy jako okno dialogowe przerywające program.","manual.b7c8c66a5330":"<strong>Panel stanu źródeł</strong> (paleta poleceń → „Stan źródeł…”) pokazuje stan każdego źródła, liczbę klatek na sekundę, wiek ostatniej klatki, utracone klatki i ponowne uruchomienia, z przyciskami <strong>Uruchom ponownie</strong> i <strong>Właściwości</strong> dla każdego z nich.","manual.92bd60ef963b":"Jeśli koder sprzętowy zawiedzie w trakcie streamu lub nagrania — reset sterownika, przeciążona karta graficzna — <strong>przełączanie kodera</strong> przechodzi na inny koder sprzętowy lub na x264. Stream łączy się ponownie i trwa dalej, nagranie jest kontynuowane w nowym pliku, a komunikat mówi dokładnie, co się stało. Problemy z siecią nigdy nie powodują przełączenia.","manual.50a02fe4fe7b":"<strong>Przycisk awaryjny</strong> (wybrany przez ciebie globalny skrót) przełącza program — oraz pionowe płótno i wszystkie projektory — na planszę prywatności, zatrzymuje każde przechwytywanie i wycisza cały dźwięk, łącznie z mikrofonem, podczas gdy stream i nagranie pozostają połączone. Powrót wymaga świadomego, dwuetapowego potwierdzenia. Ustaw kolor lub obraz planszy obok skrótu w <strong>Ustawienia → Skróty klawiszowe</strong>.","manual.a73a2857361e":"Po: bezpieczne nagrania i uporządkowane zamykanie","manual.bf07b060e7e7":"Nagrania MP4 i MOV są zapisywane we <strong>fragmentach</strong>, więc awaria lub zanik zasilania wciąż zostawiają odtwarzalny plik (MKV i <code>.frec</code> już tak działały). Jeśli sesja skończy się w trakcie nagrania, następne uruchomienie zaproponuje <strong>Napraw</strong> jednym kliknięciem do kopii <code>(repaired)</code>; oryginał nigdy nie jest ruszany.","manual.da5eeb31c1b8":"Zamknięcie aplikacji podczas transmisji na żywo, nagrywania lub z uzbrojoną powtórką pokazuje, co się stanie, a potem zamyka wszystko <strong>po kolei</strong>: kończy stream, kończy nagranie, zapisuje bufor powtórek, zapisuje twoją pracę.","manual.26b3f2c32e05":"<strong>Nazwy plików nagrań</strong> są tworzone według szablonu (<strong>Ustawienia → Wyjście</strong>) zbudowanego z tokenów — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — dla nagrań, powtórek i zrzutów klatek, z osobnymi folderami na powtórki i zrzuty.","manual.27c3f23547ac":"<strong>Eksportuj diagnostykę</strong> zapisuje pakiet szczegółów technicznych do pliku na twoim komputerze, zbudowany na podstawie ścisłej listy dozwolonych elementów, tak by nigdy nie było w nim kluczy streamu, haseł, ścieżek ani nazw plików. Możesz najpierw przeczytać, co zawiera; zostaje tam, gdzie go zapiszesz, i nigdy nie jest nigdzie wysyłany.","manual.5199babf9b90":"Źródła i urządzenia","manual.306121fdda68":"Wszystko między obiektywem a płótnem: sygnały testowe, kalibracja synchronizacji, tekst z pliku, minutniki, mapa skrótów, mikser w głąb i prawdziwe sterowanie urządzeniami.","manual.5eacf1ee941f":"Sygnały testowe i kalibracja synchronizacji A/V","manual.920b7abd63cc":"Dodaj źródło <strong>Sygnał testowy</strong> (<strong>Źródła → + → Sygnał testowy</strong>): pasy kolorów, siatka kalibracyjna, przemiatanie ruchu, ton odniesienia 1 kHz przy −20 dBFS albo połączony <strong>błysk i sygnał dźwiękowy</strong> do synchronizacji obrazu i dźwięku — obraz i dźwięk tworzone z jednego zegara. Sprawdź projektor, koder lub cel streamu bez podłączonej kamery.","manual.788073298328":"Otwórz warsztat <strong>Kalibracja synchronizacji A/V</strong> (paleta poleceń → „Kalibracja synchronizacji A/V…”). Wybierz kamerę i mikrofon do zgrania, skieruj kamerę na migający program (okno może w tym celu otworzyć projektor pełnoekranowy) i pozwól mu mierzyć przez około dwanaście sekund. Wykrywa błysk i sygnał dźwiękowy w kilku cyklach i proponuje zastosowanie zmierzonego przesunięcia do mikrofonu; ręczny suwak pozostaje jako zapas. Pomiar przechodzi przez twój ekran i głośniki, więc ich własne małe opóźnienia są jego częścią — a niepowodzenie mówi, <em>dlaczego</em>.","manual.825c83c405fb":"Minutniki, zegary i tekst z pliku","manual.85622b429b51":"Źródło <strong>Minutnik</strong> pokazuje zegar (z twoim własnym formatem i opcjonalnym stałym przesunięciem względem UTC), <strong>Odliczanie</strong> (przez określony czas lub do najbliższej podanej pory dnia — przy zerze może migać lub przełączyć scenę), <strong>Stoper</strong> albo <strong>czas od wejścia na żywo lub rozpoczęcia nagrywania</strong>. Uruchamiaj, wstrzymuj i resetuj je z jego <strong>Właściwości</strong> albo przypisz dwa globalne skróty, które sterują <em>wszystkimi</em> minutnikami naraz (<strong>Ustawienia → Skróty klawiszowe</strong>).","manual.fcd4f802968f":"Źródło <strong>Tekst</strong> może <strong>czytać z obserwowanego pliku</strong> (<strong>Właściwości → Czytaj z pliku</strong>): cały plik <code>.txt</code>, jedną komórkę CSV (według nazwy lub numeru kolumny) albo jedną wartość JSON (wskaźnik, taki jak <code>/teams/0/score</code>). Zmiany pojawiają się w ciągu pół sekundy. Tablice wyników i belki z podpisami bez żadnej usługi za nimi.","manual.1d106549f0ce":"Mapa skrótów i konsola miksera","manual.5d6ad89f147c":"<strong>Mapa skrótów</strong> (paleta poleceń → „Mapa skrótów…”) pokazuje <em>każde</em> przypisanie — akcje globalne oraz push-to-talk i push-to-mute każdego źródła — z wyszukiwaniem i filtrowaniem, i uczciwie oznacza konflikty: ten sam skrót zapisany na dwa sposoby jest pokazywany jako współdzielony, a przy klawiszu, którego system odmówił (bo należy do innej aplikacji), jest to napisane. <strong>Eksportuj ściągę</strong> zapisuje ściągawkę w formacie Markdown w folderze Pobrane.","manual.e32e382b9753":"Każdy kanał miksera ma <strong>Panoramę</strong> (balans stereo; środek to dokładnie brak panoramy, a dwukrotne kliknięcie ją resetuje), <strong>solo PFL</strong> (odsłuch słyszy tylko kanały w trybie solo; miks programu nigdy się nie zmienia) i zmiksowanie do <strong>mono</strong>. Panorama i mono są w menu „⋯” kanału; solo jest na samym kanale.","manual.5dbd70dfc92d":"Urządzenia w głąb: usuwanie przeplotu i sterowanie kamerą","manual.f8e60899a881":"<strong>Właściwości</strong> urządzenia przechwytywania wideo oferują <strong>Usuwanie przeplotu</strong> dla sygnałów z przeplotem, takich jak karty przechwytujące zasilane przez starsze kamery i konsole: odrzucanie, bob, liniowe, mieszanie lub adaptacyjne do ruchu, z kolejnością pól. Działa tak samo w każdym systemie; zmiana ustawienia uruchamia urządzenie ponownie.","manual.34192e6d30fd":"<strong>Sterowanie kamerą</strong> — ekspozycja, balans bieli, ostrość, zoom, wzmocnienie i więcej — pojawia się w tych samych <strong>Właściwościach</strong>, gdy kamera działa. Windows i Linux używają standardowych kontrolek UVC; macOS pokazuje to, co zgłasza system, czyli często nic, i panel o tym mówi, zamiast pokazywać suwaki, które nic nie robią. Każda zmiana jest zapisywana w <strong>profilu dla tej kamery</strong> i stosowana ponownie, gdy kamera zostanie znów podłączona lub aplikacja uruchomi się ponownie; <strong>Resetuj profil</strong> przywraca wartości domyślne.","manual.f77f10d8c967":"Automatyzacja i sterowanie","manual.726216fb4de1":"Pozwól studiu prowadzić się samemu dzięki regułom, makrom i kontrolerom sprzętowym — każde z nich jest ograniczone do jednej stałej listy poleceń studia, więc żadna automatyzacja nie może wskazać pliku, uruchomić programu ani połączyć się z internetem.","manual.193521bd4921":"Reguły, makra i zmienne","manual.e8ee7ccab125":"Otwórz <strong>Narzędzia → Reguły automatyzacji i makra…</strong> i dodaj regułę. Wybierz jeden z dziewięciu wyzwalaczy (zmiana sceny, rozpoczęcie lub zakończenie streamu, rozpoczęcie lub zakończenie nagrywania, błąd źródła, poziom dźwięku przekraczający próg, bezczynność systemu, okno otrzymujące fokus, pora dnia lub zmiana obserwowanego pliku), dodaj warunki (wartość zmiennej, na żywo, nagrywanie) i wybierz akcję studia. Każda reguła zaczyna jako <strong>wyłączona</strong>: włącz ją, by ją uzbroić.","manual.5deaa7ba718f":"Zbuduj makro jako nazwaną listę kroków — wykonaj akcję, odczekaj, ustaw zmienną — z liczbą powtórzeń i opcjonalnym globalnym skrótem. Uruchamiaj je z aplikacji, skrótem, regułą lub przez API zdalnego sterowania.","manual.30ee5b1326f2":"Ustaw w makrze <strong>zmienną</strong> studia i używaj jej jako <code>{{name}}</code> w dowolnym źródle Tekst: tekst zmienia się w chwili, gdy makro ustawi wartość.","manual.5eb10fc04538":"Kontrolery: MIDI, OSC i panel dotykowy","manual.ba0c838f1688":"Otwórz <strong>Narzędzia → Sterowanie MIDI…</strong> i przypisz pad, pokrętło lub suwak do akcji, makra, zmiany sceny, fadera miksera lub wyciszenia, ucząc je ruchem kontrolera — z podświetleniem i zmotoryzowanymi suwakami, które podążają za rzeczywistym stanem studia. Żaden port MIDI nie zostanie otwarty, dopóki go nie wybierzesz.","manual.cc993cb0d974":"Włącz <strong>Nasłuchuj OSC</strong>, by kontrolery w stylu TouchOSC i konsole oświetleniowe mogły wysyłać adresy takie jak <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> i <code>/mixer/vol</code>. Domyślnie jest wyłączone i nasłuchuje tylko na tym komputerze, chyba że zezwolisz na swoją sieć. OSC nie ma własnego hasła.","manual.134e5f4269f9":"Otwórz <strong>Narzędzia → Panel LAN i tally…</strong>, by udostępnić stronę sterowania — przyciski scen z tally na żywo, fadery miksera i klawisze akcji — na dowolnym telefonie przez kod QR. Każde żądanie wymaga hasła, a nasłuch działa tylko na tym komputerze, chyba że zezwolisz na swoją sieć. Strona tally pokazuje pełnoekranowy kolor czerwony lub zielony; dodaj <code>?scene=NAME</code>, by obserwować jedną scenę.","manual.fc4cd96b860d":"Akordy skrótów i warstwy","manual.ec4a9a334753":"W polu skrótu przypisz zwykły skrót (Ctrl+Shift+M) lub dwuetapowy akord (Ctrl+K, a potem 3) — drugi klawisz jest przechwytywany tylko wtedy, gdy akord czeka. Nadaj przypisaniu <strong>Warstwę</strong>, by działało tylko wtedy, gdy ta warstwa jest aktywna; warstwy pozostają przełączone, dopóki ich nie zmienisz.","manual.70ad05980925":"Kamery i scenariusz programu","manual.24b33b058b99":"Otwórz <strong>Narzędzia → Kamery PTZ…</strong>, dodaj kamerę po jej adresie VISCA-over-IP, zapisz nazwane presety panoramy, pochylenia i zoomu i powiąż preset ze sceną, aby przejście do tej sceny przywoływało ujęcie. PTZ pozostaje w twojej sieci, a kamera istnieje tylko dlatego, że wpisałeś jej adres: nic nie jest wyszukiwane.","manual.c9d86b995c5a":"Otwórz <strong>Narzędzia → Pokaż scenariusz programu…</strong> i wypisz kroki — scenę, jak długo trwa i opcjonalne akcje — przechodząc dalej ręcznie lub automatycznie, z podglądem na żywo „następny” i pozostałym czasem. Scenariusz przełącza sceny w zwykły sposób, który można cofnąć, i nigdy nie edytuje twojej kolekcji scen.","manual.5c94bed2d737":"<strong>Uwaga:</strong> Każda reguła, makro, przypisanie MIDI lub OSC, przycisk panelu i krok scenariusza przechodzi przez tę samą stałą listę poleceń co API zdalnego sterowania, więc żaden kontroler nie może zrobić tego, czego nie potrafią własne przyciski aplikacji. Każdy nasłuch sieciowy jest domyślnie wyłączony i pozostaje na tym komputerze, chyba że zezwolisz na swoją sieć, a ustawienia OSC i panelu ostrzegają cię, że ruch sieciowy nie jest szyfrowany, zanim port zostanie otwarty.","manual.1f3fd1c7ddc9":"Multistreaming","manual.dcac0a03a29b":"Streamuj na kilka platform naraz — prosto ze swojego komputera, bez usługi pośredniczącej.","manual.42d9628818da":"Dodaj dwa lub więcej celów streamu w <strong>Ustawienia → Stream</strong> i włącz każdy z nich.","manual.4144fe0d9694":"Nadaj platformie własne ustawienia kodera, jeśli potrzebuje innego bitrate.","manual.cb21d6bb96be":"Kliknij <strong>Rozpocznij transmisję</strong>: nadajesz jednocześnie do każdego włączonego celu. Dok statystyk pokazuje stan i bitrate każdego celu, a awaria jednego celu nigdy nie pociąga za sobą pozostałych.","manual.aba9a5f55973":"Opcjonalnie nagrywaj w tym samym czasie kopię lokalną z osobnymi ścieżkami i zapisuj powtórki skrótem powtórki podczas streamowania.","manual.af9343c245a7":"<strong>Dziś za darmo:</strong> każda funkcja — multistream, SRT i WHIP, każdy filtr, skrypty, powtórki, pakiety przejść i API zdalnego sterowania — jest dziś darmowa, dla wszystkich. Przyszłe wersje mogą być sprzedawane.","manual.c08320c45003":"Niezawodność i wgląd w streaming","manual.532ab322d03c":"Przećwicz, zmierz i wyjaśnij swój program. Wszystko tutaj jest domyślnie wyłączone lub neutralne i nic z tego nie łączy się z internetem.","manual.80390ae1a9d7":"Symulator sieci","manual.7e620ced841e":"W <strong>Ustawienia → Stream</strong> otwórz <strong>Symulator sieci (próby)</strong> i wybierz <strong>Profil</strong> — <strong>Hotelowe Wi-Fi</strong>, <strong>Mobilny hotspot</strong> lub <strong>Własny</strong> z własnymi wartościami <strong>Przepustowość</strong>, <strong>Opóźnienie</strong>, <strong>Jitter</strong> i zaplanowanymi czasami <strong>Przerwa</strong>. Wpływa tylko na lokalne wyjście próby, więc możesz ćwiczyć ponowne łączenie, multistream i wybór bitrate; nigdy nie może spowolnić prawdziwej transmisji.","manual.b22d8c51e0bd":"Tryb próby","manual.083772633b86":"Naciśnij fioletowy przycisk <strong>Próba</strong>, by uruchomić cały potok — kompozytor, koder, multiplekser i prawdziwą logikę ponownego łączenia — do lokalnego zastępczego odbiornika, przy czym <strong>nic nie opuszcza komputera</strong>. Plakietka <strong>PRÓBA</strong> oznacza każdy element sterujący transmisją, a twoje klucze streamu nie są nawet odczytywane, więc możesz przećwiczyć program, zanim je dostaniesz. Próbę możesz też nagrać.","manual.184d64047c4c":"<strong>Wskazówka:</strong> Połącz próbę z symulatorem sieci, by na długo przed dniem programu przećwiczyć ponowne łączenie przy słabym, niestabilnym połączeniu.","manual.d2381a584d24":"Oś czasu utraconych klatek","manual.a6a72c5410a8":"<strong>Oś czasu sesji</strong> zapisuje całą sesję — czas renderowania, kolejkę kodera, bitrate i utracone klatki każdego celu, ponowne połączenia, zmiany scen, znaczniki i alarmy — na jednym wykresie z możliwością powiększania. Tam, gdzie dok statystyk pokazuje <em>teraz</em>, oś czasu odpowiada potem na pytanie „co się stało w 43. minucie?”.","manual.6e9fee1e85fa":"Raport sesji i benchmark koderów","manual.9dd812cbf648":"Włącz <strong>Zapisuj raport sesji (HTML + Markdown) obok nagrania</strong> w <strong>Ustawienia → Stream</strong>, by po zakończeniu sesji dostać lokalne podsumowanie: czas działania, średni i szczytowy bitrate każdego celu, czas niedostępności, ponowne połączenia, znaczniki, alarmy i lokalizację nagrania. Zostaje na twoim komputerze i jest domyślnie wyłączone.","manual.a9e574b7bd8d":"Użyj <strong>Uruchom benchmark enkoderów…</strong>, by zmierzyć krótkie kodowania każdym koderem, presetem i rozdzielczością dostępnymi na twoim komputerze — około minuty, całkowicie offline — a potem z wyniku wybierz <strong>Zastosuj do ustawień nagrywania</strong>. Niepowodzenia są wymienione, a nie ukryte, a benchmark odmawia uruchomienia, gdy jesteś na żywo lub nagrywasz.","manual.fae310275ed2":"Źródła tylko w streamie albo tylko w nagraniu","manual.191da176dd0d":"W wierszu źródła użyj <strong>Pokaż w streamie</strong> / <strong>Ukryj w streamie</strong> oraz <strong>Pokaż w nagraniu</strong> / <strong>Ukryj w nagraniu</strong>, by alerty i czat były widoczne w transmisji na żywo, a nagranie pozostało czyste — z jednego płótna. Główny przycisk z okiem nadal steruje wszystkim, a podgląd, projektory i widok wielokamerowy zawsze pokazują cały program.","manual.46bad2cb618f":"Wirtualna kamera","manual.69ebe5277092":"Używaj swojego programu jako kamery internetowej w dowolnej aplikacji do wideorozmów. <strong>W 1.2.1 tylko w Windows.</strong>","manual.ba2b6aa952f7":"Kliknij <strong>Uruchom wirtualną kamerę</strong> w doku <strong>Sterowanie</strong>. Freally Capture dodaje kamerę systemową o nazwie <strong>„Freally Capture Virtual Camera”</strong>.","manual.cb3cb4585f19":"W Zoom, Meet, Discord lub Teams wybierz tę kamerę w ustawieniach wideo: twój program staje się kamerą internetową.","manual.83db59f4a370":"Kliknij <strong>Zatrzymaj wirtualną kamerę</strong>, by ją usunąć.","manual.91c51d55639b":"<strong>W poszczególnych systemach:</strong> w <strong>Windows</strong> kamera rejestruje się dla twojego użytkownika, bez uprawnień administratora, i jest usuwana, gdy ją zatrzymasz. <strong>Nie jest jeszcze podpisana cyfrowo</strong>, więc Windows może ostrzegać przed nią, a zabezpieczona aplikacja do wideorozmów może ją odrzucić; pełny test w trakcie prawdziwej rozmowy wciąż jest do zrobienia. Kamery dla <strong>macOS</strong> i <strong>Linux</strong> to osobne komponenty, których <em>nie ma w tym wydaniu</em>. Freally Capture nigdy, w żadnym systemie, nie instaluje komponentu systemowego bez pytania.","manual.98839b8e6880":"Źródło przeglądarki","manual.3ba821584b20":"Umieść stronę internetową na żywo — nakładkę alertów, tablicę wyników, widżet czatu — prosto w scenie.","manual.895f07f428cd":"W doku <strong>Źródła</strong> kliknij <strong>+</strong> i wybierz <strong>Przeglądarka</strong>.","manual.868ee19e975e":"Wklej adres <strong>http://</strong> lub <strong>https://</strong> i ustaw rozmiar oraz liczbę klatek na sekundę, z jaką ma być renderowany.","manual.292e94b0a782":"Za pierwszym razem Freally Capture zaproponuje instalację komponentu <strong>Środowisko uruchomieniowe przeglądarki</strong>. Jest pobierany, gdy o niego poprosisz, i sprawdzany względem skrótu — nigdy nie jest dołączany do aplikacji — a możesz go ponownie usunąć w <strong>Narzędzia → Komponenty</strong>.","manual.cd6d7fbd46ee":"<strong>Wczytują się tylko http i https.</strong> Reguła obejmuje każdą zmianę strony, a nie tylko wpisany adres: jeśli strona spróbuje przejść do <code>file://</code>, <code>javascript:</code> lub <code>data:</code> — przez przekierowanie, skrypt, wyskakujące okno lub ramkę — przejście zostaje <strong>anulowane</strong>, więc strona nie może czytać twoich plików. W Windows strona działa w piaskownicy Chromium. Środowisko uruchomieniowe <strong>nie jest jeszcze podpisane cyfrowo</strong>. Dźwięk strony nie jest jeszcze przechwytywany: ta wersja przechwytuje tylko obraz.","manual.9c0c8f127dd9":"Przechwytywanie gier","manual.2c08692420b8":"Przechwyć grę w trybie wyłącznego pełnego ekranu, której zwykłe przechwytywanie okna nie widzi. <strong>Tylko w Windows.</strong>","manual.9d162e3861e9":"W doku <strong>Źródła</strong> kliknij <strong>+</strong> i wybierz <strong>Przechwytywanie gry</strong>. <strong>Najpierw przeczytaj komunikat</strong>: wyjaśnia ryzyko prostymi słowami.","manual.4264b41a7732":"Zaakceptuj ryzyko <em>dla tej jednej gry</em>, a potem wybierz działającą grę z listy.","manual.ab3e826e90f1":"Freally Capture ładuje do tej gry mały hook i pobiera jej klatki z jej własną liczbą klatek na sekundę.","manual.082fd06e18f9":"<strong>Przeczytaj to, zanim tego użyjesz.</strong> Przechwytywanie gier działa przez <strong>załadowanie biblioteki DLL do gry</strong>. Oprogramowanie anti-cheat i antywirusowe może uznać to za ingerencję, a to może skończyć się <strong>banem</strong> konta. Nic nigdy nie jest ładowane automatycznie: zgadzasz się <strong>dla jednej gry naraz</strong>, a tej zgody nigdy nie można użyć dla innej gry — i nigdy nie jest przenoszona w udostępnionej kolekcji scen. Jeśli gra odrzuci hook, Freally Capture zamiast zawieść przechodzi na zwykłe <strong>Przechwytywanie okna</strong> z komunikatem. Gry HDR i gry Direct3D 12 również używają przechwytywania okna. W macOS i Linux to źródło nie jest dostępne.","manual.43fae75af922":"Bufor powtórek","manual.40bc664c1c0b":"Trzymaj ostatnie chwile w pamięci, aby skrót zapisał to, co właśnie się wydarzyło.","manual.7a69241c10c2":"Kliknij <strong>Uruchom bufor powtórek</strong> w doku <strong>Sterowanie</strong>. Freally Capture przechowuje ostatnie sekundy w buforze o stałym rozmiarze.","manual.684aecea2ba0":"Przypisz globalny skrót <strong>Zapisz powtórkę</strong> w <strong>Ustawieniach</strong>.","manual.66c44777e965":"Naciśnij go, by zapisać ostatnie sekundy do pliku — bez przerywania streamu ani głównego nagrania. Potwierdza to komunikat „Zapisano powtórkę”.","manual.4b598d5daf11":"Prompter","manual.b7fc474ded62":"Płynnie przewijany tekst dla osoby przed kamerą — jednocześnie w panelu w aplikacji, na pełnoekranowym projektorze, który można odbić lustrzanie, i na dotykowym panelu w sieci LAN.","manual.f1c548f77750":"Otwórz prompter z menu <strong>Narzędzia</strong>, wpisz lub wklej tekst i ustaw prędkość oraz czcionkę. Ustal tempo w <strong>znakach na sekundę</strong> albo przełącz na <strong>BPM</strong> (50–250 uderzeń na minutę), by czytać tekst piosenki w rytm muzyki; każda z tych zmian dostosowuje tempo trwającego przewijania.","manual.3a86eb91938d":"<strong>Znaczniki pauz:</strong> wpisz <code> -- </code> dla krótkiej pauzy lub <code> --N </code> dla N-sekundowego zatrzymania, a zmieni się to w pojedynczy znacznik — kursor go przeskakuje, jedno naciśnięcie Delete lub Backspace go usuwa, a kopiowanie i wklejanie zachowuje go w całości.","manual.dc7539148aed":"<strong>Rozpocznij odliczanie:</strong> uzbrój opcjonalne odliczanie 3-2-1, pokazywane zarówno w podglądzie operatora, jak i na projektorze, aby czytający miał chwilę, zanim tekst ruszy.","manual.f5113c573ac4":"<strong>Otwórz projektor</strong> dla czytającego (tryb lustrzany odwraca obraz dla szyby półprzepuszczalnej). Otwarcie go zamyka okno operatora, więc możesz prowadzić stream z głównego okna, gdy czytający czyta; przy uzbrojonym odliczaniu projektor wraca na początek, odlicza i startuje. Odtwarzaj, wstrzymuj, zatrzymuj, przewijaj do tyłu, do przodu i zaczynaj od nowa za pomocą przycisków na ekranie, skrótu, MIDI, OSC lub panelu LAN — każdy element sterujący pozostaje zsynchronizowany.","manual.5298a60b0152":"<strong>Czytaj na głos</strong> pozwala odsłuchać tekst przy użyciu syntezy mowy twojego systemu: wbudowanych głosów Windows, macOS, a w Linux <code>spd-say</code> lub <code>espeak-ng</code>, jeśli są zainstalowane. Żaden silnik mowy nie jest dołączony.","manual.5de1b5efa245":"<strong>Autouzupełnianie</strong> podpowiada słowa i frazy jasnoszarym tekstem podczas pisania; naciśnij Tab, by zaakceptować. Każdy z 18 języków ma własny słownik na twoim komputerze, wczytywany tylko dla języka, w którym piszesz.","manual.7fb5d22a1670":"Zdalne sterowanie","manual.b2ba73efdcec":"Steruj studiem ze Stream Decka lub kontrolera w stylu Companion — domyślnie wyłączone, chronione hasłem, na twoim własnym komputerze.","manual.6396674fcd28":"Otwórz <strong>Ustawienia → Zdalne sterowanie</strong>, włącz <strong>API WebSocket</strong> (domyślnie wyłączone) i ustaw <strong>Hasło</strong>.","manual.56e0d6d295bb":"Nasłuchuje na <code>127.0.0.1</code> — tylko na tym komputerze — chyba że jawnie zezwolisz na swoją sieć.","manual.344e52e3eba1":"Skieruj klienta Companion lub Stream Deck na pokazany adres. Przełączaj sceny, uruchamiaj przejścia, wyciszaj i włączaj dźwięk, rozpoczynaj i zatrzymuj nagrywanie oraz zapisuj powtórki przyciskami sprzętowymi.","manual.6664edd9ad4c":"Goście zdalni i produkcja programu","manual.75ce17238f9b":"Zamień sesję z gośćmi zdalnymi w wyprodukowany program: do ośmiu gości, rysowanie po programie na żywo, poczekalnia, prywatne sygnały, połączenie każdego gościa na pierwszy rzut oka i automatyczna siatka. Wszystko tutaj jest domyślnie wyłączone lub nieprzypisane i nic się nie łączy, dopóki kogoś nie zaprosisz.","manual.02d9e34002c8":"Sesje z wieloma gośćmi","manual.5a6c2ec7640d":"Rozpocznij sesję z gośćmi zdalnymi i udostępnij link z zaproszeniem lub jego kod QR: <strong>ty plus do ośmiu gości</strong>, galeria od jednego do dziewięciu kafelków. Każdy gość to kafelek z własnymi przyciskami wyciszania, jakością połączenia, kanałem sygnałów i wpuszczaniem na antenę jednym kliknięciem.","manual.34a323a45540":"Gość otwiera link w przeglądarce — bez instalowania czegokolwiek — i dotyka <strong>Dołącz</strong>, by wysłać obraz z kamery i dźwięk z mikrofonu. Gość, który ma Freally Capture, może zamiast tego otworzyć to samo zaproszenie w aplikacji. Zaproszenie wygasa po wybranym przez ciebie czasie.","manual.4e31042e4a6f":"<strong>Uwaga:</strong> Obraz i dźwięk płyną bezpośrednio między tobą a każdym gościem, peer-to-peer i z szyfrowaniem w trakcie przesyłania; tylko nawiązanie połączenia przechodzi przez publiczną usługę sygnalizacyjną. Sesje są testowane z czterema gośćmi; więcej zależy od twojego łącza i procesora.","manual.33ff43cd0616":"Telestrator: rysuj po programie na żywo","manual.d29f651d6eb9":"Otwórz <strong>Telestrator</strong> i wybierz narzędzie — <strong>Pióro</strong>, <strong>Zakreślacz</strong>, <strong>Strzałka</strong> lub <strong>Elipsa</strong> — a potem rysuj prosto po programie. Twoje znaki stają się częścią obrazu w chwili narysowania, więc pojawiają się w nagraniu i streamie, a nie tylko w twoim podglądzie.","manual.9aa7fc0273fb":"Ustaw znaki na <strong>Zanikanie</strong> po pewnym czasie albo przełącz na <strong>Tryb tablicy</strong> i wybierz <strong>Zachowaj</strong>, by zostawały, dopóki ich nie wyczyścisz. Rysowanie uwzględnia nacisk tabletu, a <strong>Wyczyść znaki</strong> można przypisać do skrótu (domyślnie nieprzypisane).","manual.fc81cd8d37ae":"Poczekalnia","manual.c87beb96ec64":"Włącz <strong>Poczekalnię</strong>, a nowi goście czekają poza anteną, podczas gdy ty sprawdzasz ich kamerę i mikrofon w <strong>Podglądzie poczekalni</strong>. Gdy są gotowi, kliknij <strong>Na antenę</strong>. Gość widzi baner „jesteś w poczekalni” w aplikacji lub na stronie internetowej.","manual.1d47c8224f50":"Sygnały i rozmowa","manual.569d461035c1":"Wyślij gościowi prywatny <strong>Sygnał</strong> — z gotowymi opcjami, takimi jak <strong>30 sekund</strong>, <strong>Kończ</strong>, <strong>Zaraz twoja kolej</strong> i <strong>Mów głośniej</strong> — przez istniejący kanał peer-to-peer sesji. Gość widzi go z odliczaniem na żywo, nigdy w programie.","manual.c66c9d5359bf":"Panel jakości połączenia","manual.4541cc1ee0f5":"Obserwuj na żywo połączenie każdego gościa — czas obiegu, utratę pakietów, odbieraną rozdzielczość i liczbę klatek na sekundę oraz jitter — z zieloną, bursztynową lub czerwoną plakietką i małym wykresem historii, więc słabnące połączenie widać, zanim zauważą to twoi widzowie.","manual.bf8e764221e5":"Automatyczne siatki gości","manual.ffe3c227cdfc":"Włącz <strong>Auto-siatkę</strong>, by utrzymywać gości na antenie w uporządkowanej siatce od jednego do dziewięciu kafelków, która sama się przestawia, gdy goście dołączają, wychodzą lub są wpuszczani na antenę, albo naciśnij przycisk układania, by zrobić to od razu. Każde miejsce publikuje imię swojego gościa jako zmienną <code>{{guestN}}</code>, więc źródło tytułu staje się podpisem, który sam się aktualizuje.","manual.e8630fabd4e5":"Zarządzanie studiem i przepływ pracy","manual.c8c487196725":"Spraw, by cały układ dało się przenosić i udostępniać, przechowuj nazwane wersje swoich scen, nadaj aplikacji motyw i miej ulubione akcje na jedno dotknięcie — wszystko na twoim komputerze, bez serwera.","manual.f87995a7cf6c":"Pakiety scen i wersje","manual.074bb2bf9453":"Otwórz okno obszaru roboczego z <strong>Kolekcja scen → Zarządzaj kolekcjami scen…</strong>: są tam wszystkie narzędzia do pakietów, porównywania, migawek, kopii zapasowych i układów doków.","manual.8dce3a052a05":"Kliknij <strong>Eksportuj pakiet…</strong>, by spakować bieżącą kolekcję i jej pliki (obrazy, multimedia, LUT-y, maski, fonty) w jeden przenośny plik <code>.fcappack</code>. Adresy internetowe i ścieżki sieciowe są wymienione jako <em>zewnętrzne</em>, a nie dołączane, a fonty są oznaczane ze względu na licencje.","manual.c1bba88df9c5":"Kliknij <strong>Importuj pakiet…</strong> i wybierz plik <code>.fcappack</code>: trafia on jako nowa kolekcja, odnajduje swoje pliki na tym komputerze i przełącza się na nią.","manual.69e7b9f6e8ab":"Kliknij <strong>Porównaj i scal…</strong>, by porównać bieżącą kolekcję z inną kolekcją, pakietem lub migawką. Przejrzyj dodane, usunięte i zmienione sceny, źródła, transformacje, filtry i widoczność, a potem wybierz dokładnie, które zmiany przenieść. Wybranie sceny przenosi źródła, których używa.","manual.862a75c84629":"Kliknij <strong>Migawki…</strong>, nazwij punkt kontrolny i wybierz <strong>Zapisz migawkę</strong>. <strong>Przywróć</strong> przywraca go później — twój bieżący układ jest najpierw zapisywany jako migawka, więc przywrócenie nigdy nie jest nieodwracalne. Przechowywanych jest do 50 migawek, z widocznym zajętym miejscem na dysku.","manual.8058b1480d14":"<strong>Wskazówka:</strong> Migawki to nazwana historia obok automatycznego zapisu i cofania. Zrób migawkę przed ryzykowną zmianą, a zawsze będziesz mieć opisany punkt, do którego możesz wrócić.","manual.1d55a62a5fdf":"Kopia zapasowa, przywracanie i tryb przenośny","manual.250b89a976de":"W oknie obszaru roboczego kliknij <strong>Kopia zapasowa i przywracanie…</strong>, a potem <strong>Eksportuj kopię zapasową…</strong>, by zapisać wszystko — ustawienia, profile i kolekcje scen — w jednym pliku <code>.fcapbackup</code>.","manual.560e7e269f11":"Na nowym komputerze kliknij <strong>Przywróć z kopii zapasowej…</strong>, zaznacz, co ma zostać przeniesione (<strong>Ustawienia</strong>, <strong>Kolekcje scen</strong>, <strong>Profile</strong>), i wybierz <strong>Przywróć wybrane</strong>. Potem uruchom ponownie Freally Capture, by wczytać przywrócone kolekcje i profile.","manual.5b26da4b8793":"Aby uruchamiać aplikację z pendrive’a, umieść obok programu plik o nazwie <code>freally-portable.txt</code>: wszystkie jego dane będą wtedy przechowywane w folderze programu zamiast w twoim profilu użytkownika. <strong>Ustawienia → Informacje</strong> pokazuje, czy tryb przenośny jest włączony i gdzie są dane.","manual.a31a49d41d7d":"<strong>Uwaga:</strong> Klucze streamu i hasła nigdy nie są zapisywane w kopii zapasowej — po przywróceniu wprowadź je ponownie.","manual.5b446c4ea972":"Motywy, układy i szybkie akcje","manual.8eea476bde73":"Otwórz <strong>Ustawienia → Wygląd</strong> i wybierz motyw <strong>Własny</strong>, by edytować paletę z <strong>ostrzeżeniami o kontraście</strong> na żywo, a potem <strong>Eksportuj .fctheme…</strong> lub <strong>Importuj .fctheme…</strong>, by ją udostępnić.","manual.7cc0bc3a4e74":"W sekcji <strong>Układy doków</strong> okna obszaru roboczego zapisz bieżący układ pod nazwą i kliknij zapisany układ, by się na niego przełączyć.","manual.c9044c09b979":"W <strong>Ustawieniach</strong> wpisz tekst w polu <strong>Szukaj ustawień…</strong>, by przejść do dowolnego ustawienia; znacznik pokazuje, które kategorie zmieniłeś od otwarcia okna.","manual.a4640858ad4d":"Wybierz <strong>Narzędzia → Szybkie akcje…</strong>, by otworzyć siatkę przycisków. Kliknij <strong>Edytuj</strong>, a potem <strong>Dodaj przycisk</strong>, ustaw etykietę i kolor każdego przycisku i dodawaj <strong>strony</strong>. Przycisk może przełączyć scenę, uruchomić makro, odtworzyć pad soundboardu lub wykonać polecenie studia.","manual.74ff6472576d":"<strong>Wskazówka:</strong> Przyciski szybkich akcji wykonują te same polecenia studia co skróty klawiszowe, a siatka jest współdzielona z dotykowym panelem w sieci LAN: skonfiguruj ją raz, a będzie też na twoim telefonie.","manual.74a883a037bc":"Ustawienia","manual.5feaf4600834":"Profile, kolekcje scen, skróty klawiszowe i język. Wszystko jest dziś darmowe, więc nie ma niczego do aktywowania. <strong>Ustawienia</strong> to jedno okno z kategoriami — Ogólne, Wygląd, Streaming, Wyjście, Powtórka, Skróty klawiszowe, Sieć, Dostępność i Informacje — otwierane z <strong>paska menu</strong> (Plik, Edycja, Widok, Doki, Profil, Kolekcja scen, Narzędzia i Pomoc).","manual.9f6a04e85e39":"<strong>Zastosuj znaczy zastosuj.</strong> Okno Ustawień edytuje kopię: nic się nie zmienia, dopóki nie klikniesz <strong>Zastosuj</strong> lub <strong>OK</strong>, a <strong>Anuluj</strong> przywraca dokładnie to, co było, łącznie z podglądem motywu.","manual.3fc0968ef6f9":"<strong>Profile i kolekcje scen:</strong> trzymaj osobne konfiguracje — na przykład „Streaming” i „Nagrywanie lokalne” — i przełączaj się między nimi bez ponownego uruchamiania, z menu <strong>Profil</strong> i <strong>Kolekcja scen</strong>.","manual.ce6f52861bdb":"<strong>Skróty klawiszowe:</strong> przypisz każdą akcję z listy, w której nie może dojść do konfliktu — wybierz skrót dla jednej akcji, a zniknie z list wszystkich pozostałych akcji, więc dwie funkcje nigdy nie dzielą klawisza. <strong>Brak</strong> ponownie go zwalnia.","manual.be52349f05be":"<strong>Dostępność:</strong> wybierz kolory mierników miksera, w tym zestaw bezpieczny dla osób z zaburzeniami widzenia barw. Całą aplikację można obsługiwać z klawiatury, a czytniki ekranu ogłaszają wejście na żywo, nagrywanie, ponowne łączenie i utracone klatki.","manual.a79c94673558":"<strong>Język:</strong> wybierz jeden z 18 języków; aplikacja zmienia się od razu, a arabski czyta się od prawej do lewej.","manual.59274c49ac87":"Zgłaszanie problemu","manual.c02ed8aec89d":"To ty decydujesz, czy problem trafi do twórcy, i widzisz dokładnie, co zostałoby wysłane.","manual.4ed327c34aeb":"Gdy aplikacja pokazuje błąd, który sama spowodowała, obok niego pojawia się przycisk <strong>Zgłoś</strong>.","manual.95da4b53fdcc":"Po awarii następne uruchomienie proponuje <strong>Zgłoś</strong> lub <strong>Odrzuć</strong>.","manual.6207904599f4":"<strong>Zgłoś</strong> otwiera w przeglądarce stronę zgłoszeń Freally Capture w tej witrynie, z już wypełnionymi danymi technicznymi: możesz je przeczytać, ale nie możesz ich zmienić. Dopisz, co robiłeś, i jeśli chcesz, adres e-mail. Nic nie zostanie wysłane, dopóki nie naciśniesz tam <strong>Wyślij</strong>.","manual.6acd4e789ccd":"Nic nigdy nie jest wysyłane w tle, a <strong>Odrzuć</strong> nie wysyła zupełnie niczego.","manual.69bd78234ffb":"Prywatność i sieć","manual.42f9b04c2640":"Freally Capture nie ma konta ani telemetrii i nie ma żadnej naszej usługi w chmurze. Oto dokładnie, co łączy się z internetem, a co nie.","manual.81fe73d241a8":"<strong>Bez konta, bez telemetrii.</strong> Aplikacja nigdy nie prosi cię o zalogowanie i nigdy nigdzie nie wysyła twoich scen, nagrań ani żadnych danych o użytkowaniu.","manual.3735a28566e9":"<strong>Twój stream trafia prosto na platformę.</strong> Wędruje z twojego komputera do skonfigurowanych przez ciebie usług — nie ma żadnego naszego serwera pośredniczącego.","manual.512b8fa00684":"<strong>Twoje nagrania zostają na twoim komputerze,</strong> w wybranym przez ciebie folderze. Nic nie jest przesyłane.","manual.c299fcfa1fde":"<strong>Twoje klucze streamu zostają na twoim komputerze,</strong> są wyświetlane w zamaskowanej formie i wysyłane tylko do usługi, na którą streamujesz.","manual.414a08bd0219":"<strong>Goście zdalni łączą się peer-to-peer.</strong> Tylko nawiązanie połączenia w sesji przechodzi przez publiczną usługę sygnalizacyjną i tylko wtedy, gdy rozpoczynasz sesję.","manual.20c95c4687b3":"<strong>Nakładka czatu czyta publiczny czat</strong> kanału, który jej wskażesz, tak jak widziałby go niezalogowany widz — bez konta, klucza ani logowania.","manual.efe87d55bed1":"<strong>Dwa komponenty są pobierane dopiero wtedy, gdy pierwszy raz ich potrzebujesz:</strong> ffmpeg, dla kodeków wymaganych przez platformy, i środowisko uruchomieniowe przeglądarki, dla źródła przeglądarki. Każdy pochodzi od własnego wydawcy i jest sprawdzany przed użyciem.","manual.3601a272b3b0":"<strong>Sprawdzanie aktualizacji</strong> pobiera jeden mały plik raz przy każdym uruchomieniu oraz wtedy, gdy wybierzesz <strong>Sprawdź aktualizacje…</strong>. Nie jest przy tym wysyłane nic o tobie ani o twoim komputerze i nic nie jest instalowane, dopóki się nie zgodzisz.","manual.11abc96d8e21":"<strong>Zgłoszenie problemu jest wysyłane tylko wtedy, gdy naciśniesz Wyślij</strong> na stronie zgłoszenia, po przeczytaniu, co zawiera (zobacz <a href=\"#report\">Zgłaszanie problemu</a>).","manual.804fa6536d40":"<strong>Bez AI.</strong> Każdy filtr — redukcja szumów, chroma key, mapowanie tonów — to klasyczne przetwarzanie sygnału. Aplikacja nie zawiera żadnego modelu uczenia maszynowego i żadnego nie pobiera."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
